/**
 * sync-social-tags.mjs — writes the Open Graph / X (Twitter) card tags every indexable page
 * shares, so they are never hand-copied page by page.
 *
 * Each page keeps its own <title>, meta description, og:title, og:description and og:url
 * (hand-written, or generated by sync-tax-brackets.mjs). This script owns only the region
 * between `<!-- seo:social:start -->` and `<!-- seo:social:end -->`, inserted right after
 * the page's og:url tag, and fills it with:
 *   og:site_name, og:image (+ width, height, alt), twitter:card,
 *   twitter:title / twitter:description  — copied verbatim from the page's og:title / og:description
 *   twitter:image
 *
 * Run it after editing any og:title / og:description, and after sync-tax-brackets.mjs
 * (which rewrites og:title / og:description on the bracket pages).
 *
 * USAGE
 *   node scripts/sync-social-tags.mjs           # rewrite every indexable page
 *   node scripts/sync-social-tags.mjs --check   # exit 1 if any page differs from what it would write
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { ROOT, htmlPages, isIndexable } from './seo-pages.mjs';

export const SITE = 'https://calc-hq.ca';
export const OG_IMAGE = `${SITE}/assets/img/og-default.png`;
const START = '<!-- seo:social:start -->', END = '<!-- seo:social:end -->';

const attr = (html, re) => (html.match(re) || [])[1];

function block(html, file) {
  const ogTitle = attr(html, /<meta property="og:title" content="([^"]*)">/);
  const ogDesc = attr(html, /<meta property="og:description" content="([^"]*)">/);
  if (!ogTitle || !ogDesc) throw new Error(`${file}: missing og:title or og:description`);
  const alt = html.includes('lang="fr') ? 'calc-hq.ca — calculateurs de paie, d’impôt et de prestations' : 'calc-hq.ca — Canadian payroll, tax and benefit calculators';
  return `${START}
<meta property="og:site_name" content="calc-hq.ca">
<meta property="og:image" content="${OG_IMAGE}">
<meta property="og:image:width" content="1200">
<meta property="og:image:height" content="630">
<meta property="og:image:alt" content="${alt}">
<meta name="twitter:card" content="summary_large_image">
<meta name="twitter:title" content="${ogTitle}">
<meta name="twitter:description" content="${ogDesc}">
<meta name="twitter:image" content="${OG_IMAGE}">
${END}`;
}

export function render(html, file) {
  const want = block(html, file);
  const region = new RegExp(`${START}[\\s\\S]*?${END}`);
  if (region.test(html)) return html.replace(region, want);
  const ogUrl = html.match(/<meta property="og:url" content="[^"]*">\n?/);
  if (!ogUrl) throw new Error(`${file}: no og:url tag to anchor the social block after`);
  const at = ogUrl.index + ogUrl[0].length;
  return html.slice(0, at) + (ogUrl[0].endsWith('\n') ? '' : '\n') + want + '\n' + html.slice(at);
}

const isMain = import.meta.url === `file://${process.argv[1]}`;
if (isMain) {
  const check = process.argv.includes('--check');
  let drift = 0, n = 0;
  for (const file of htmlPages()) {
    const html = readFileSync(join(ROOT, file), 'utf8');
    if (!isIndexable(html)) continue;
    n++;
    const out = render(html, file);
    if (out === html) continue;
    drift++;
    if (check) console.log(`  differs ${file}`);
    else { writeFileSync(join(ROOT, file), out); console.log(`  wrote   ${file}`); }
  }
  if (check) {
    console.log(drift ? `\nFAIL — ${drift} page(s) out of sync.` : `\nPASS — ${n} page(s) carry the shared social tags.`);
    process.exit(drift ? 1 : 0);
  }
}
